namespace CartonPacking;

public sealed class CartonPacker
{
    public PackingResult Pack(PackingProblem problem)
    {
        ArgumentNullException.ThrowIfNull(problem);

        var container = problem.Container;
        var cartons = problem.Cartons.OrderBy(c => c.Id, StringComparer.Ordinal).ToArray();
        
        // Track placements and usage counts per carton id.
        var placements = new List<Placement>();
        var usedCount = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (var c in cartons) usedCount[c.Id] = 0;

        long currentWeight = 0;
        // Precompute orientations per carton for deterministic iteration.
        var orientations = cartons.ToDictionary(c => c.Id, c => OrientationGenerator.GetOrientations(c));
        // Helper to test if candidate placement is valid.        bool CanPlace(CartonType carton, OrientedDimensions dim, int instance, int x, int y, int z)        {            // bounds            if (x < 0 || y < 0 || z < 0) return false;            if (x + dim.Width > container.Width) return false;            if (y + dim.Depth > container.Depth) return false;            if (z + dim.Height > container.Height) return false;            // weight limit            if (currentWeight + carton.Weight > container.MaxWeight) return false;            var candidate = new Placement(carton.Id, instance, x, y, z, dim.Width, dim.Depth, dim.Height);            // overlap            foreach (var p in placements)            {                if (PackingValidator.Overlaps(p, candidate)) return false;            }            // support            if (z > 0 && !PackingValidator.HasFullBaseSupport(candidate, placements)) return false;            return true;        }        // Greedy scan: iterate through z, x, y coordinates deterministically and try to place best candidate.        for (var z = 0; z < container.Height; z++)        {            for (var x = 0; x < container.Width; x++)            {                for (var y = 0; y < container.Depth; y++)                {                    // Skip if the origin (x,y,z) is already inside an existing placement.                    bool originBlocked = false;                    foreach (var p in placements)                    {                        if (x >= p.X && x < p.X + p.Width                            && y >= p.Y && y < p.Y + p.Depth                            && z >= p.Z && z < p.Z + p.Height)                        {                            originBlocked = true; break;                        }                    }                    if (originBlocked) continue;                    // Build candidate list at this origin.                    var candidates = new List<(CartonType Carton, OrientedDimensions Dim, int Instance)>();                    foreach (var carton in cartons)                    {                        var remaining = carton.Quantity - usedCount[carton.Id];                        if (remaining <= 0) continue;                        var orients = orientations[carton.Id];                        for (var oi = 0; oi < orients.Count; oi++)                        {                            var dim = orients[oi];                            // Check fit and feasibility.                            var instance = usedCount[carton.Id];                            if (CanPlace(carton, dim, instance, x, y, z))                            {                                candidates.Add((carton, dim, instance));                            }                        }                    }                    if (candidates.Count == 0) continue;                    // Choose best candidate by deterministic greedy metric:                    // 1) value/weight desc (weight==0 -> inf), 2) value desc, 3) volume desc,                    // 4) carton id asc, 5) width asc, depth asc, height asc.                    var chosen = candidates                        .OrderByDescending(c => c.Carton.Weight == 0 ? double.PositiveInfinity : (double)c.Carton.Value / c.Carton.Weight)                        .ThenByDescending(c => c.Carton.Value)                        .ThenByDescending(c => (long)c.Dim.Width * c.Dim.Depth * c.Dim.Height)                        .ThenBy(c => c.Carton.Id, StringComparer.Ordinal)                        .ThenBy(c => c.Dim.Width)                        .ThenBy(c => c.Dim.Depth)                        .ThenBy(c => c.Dim.Height)                        .First();                    // Place it.                    var place = new Placement(                        chosen.Carton.Id,                        chosen.Instance,                        x, y, z,                        chosen.Dim.Width,                        chosen.Dim.Depth,                        chosen.Dim.Height);                    placements.Add(place);                    usedCount[chosen.Carton.Id] = chosen.Instance + 1;                    currentWeight += chosen.Carton.Weight;                    // If container weight reached, we can stop early if no lighter items remain.                    if (currentWeight >= container.MaxWeight)                    {                        // continue scanning to ensure deterministic behavior but candidates will fail weight checks.                    }                }            }        }        // Final sort as required: carton id, instance, X, Y, Z.        var sorted = placements            .OrderBy(p => p.CartonId, StringComparer.Ordinal)            .ThenBy(p => p.Instance)            .ThenBy(p => p.X)            .ThenBy(p => p.Y)            .ThenBy(p => p.Z)            .ToList();        return new PackingResult(sorted);    }}